<?php namespace App\Http\Controllers;
use App\Models\{Purchase,PurchaseItem,Product,Supplier}; use App\Services\InventoryService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class PurchaseController extends Controller {
 public function index(){return view('purchases.index',['purchases'=>Purchase::with('supplier')->latest()->paginate(20)]);}
 public function create(){return view('purchases.form',['products'=>Product::where('status','active')->get(),'suppliers'=>Supplier::where('status','active')->get()]);}
 public function store(Request $r,InventoryService $inv){$d=$r->validate(['supplier_id'=>'nullable|exists:suppliers,id','items'=>'required|array|min:1','items.*.product_id'=>'required|exists:products,id','items.*.quantity'=>'required|numeric|min:.001','items.*.unit_cost'=>'required|numeric|min:0','paid'=>'required|numeric|min:0']);return DB::transaction(function()use($d,$r,$inv){$sub=collect($d['items'])->sum(fn($x)=>$x['quantity']*$x['unit_cost']);$total=$sub;$paid=$d['paid'];$p=Purchase::create(['reference_no'=>'PUR-'.now()->format('YmdHis').'-'.Str::upper(Str::random(3)),'supplier_id'=>$d['supplier_id']??null,'user_id'=>$r->user()->id,'subtotal'=>$sub,'total'=>$total,'paid'=>$paid,'due'=>max(0,$total-$paid),'status'=>'received']);foreach($d['items'] as $it){$prod=Product::whereKey($it['product_id'])->lockForUpdate()->firstOrFail();$line=$it['quantity']*$it['unit_cost'];PurchaseItem::create(['purchase_id'=>$p->id,'product_id'=>$prod->id,'quantity'=>$it['quantity'],'unit_cost'=>$it['unit_cost'],'line_total'=>$line]);$inv->change($prod,$it['quantity'],'PURCHASE',Purchase::class,$p->id,$r->user()->id,'Purchase received');}return redirect()->route('purchases.index')->with('success','Purchase completed.');});}
 public function show(Purchase $purchase){$purchase->load(['supplier','items.product']);return view('purchases.show',compact('purchase'));}}
